import sys
import math

class LuckyTickets:
    MOD = 998244353

    def solve(self, N, k, vals):
        dig = [0] * 11
        for val in vals:
            dig[10 - val] = 1
        half = N // 2
        res = [1]
        while half > 0:
            if half & 1:
                res = self.convoluteSimply(res.copy(), dig.copy(), self.MOD, 3)
            dig = self.convoluteSimply(dig.copy(), dig.copy(), self.MOD, 3)
            half >>= 1
        total = 0
        for v in res:
            total += v * v
            total %= self.MOD
        return total

    @staticmethod
    def convoluteSimply(a, b, P, g):
        m = max(2, 1 << (max(a.__len__(), b.__len__()) - 1).bit_length() + 2)
        fa = LuckyTickets.nttmb(a, m, False, P, g)
        fb = fa if a == b else LuckyTickets.nttmb(b, m, False, P, g)
        for i in range(m):
            fa[i] = fa[i] * fb[i] % P
        return LuckyTickets.nttmb(fa, m, True, P, g)

    @staticmethod
    def nttmb(src, n, inverse, P, g):
        dst = src[:n] + [0] * (n - len(src))
        h = n.bit_length() - 1
        K = 1 << (h + 1)
        H = (K.bit_length() - 1) * 2
        M = (K * K) // P
        wws = [0] * (1 << (h - 1))
        dw = pow(g, P - 1 - (P - 1) // n, P) if inverse else pow(g, (P - 1) // n, P)
        w = (1 << 32) % P
        for k in range(1 << (h - 1)):
            wws[k] = int(w)
            w = LuckyTickets.modh(w * dw, M, H, P)
        J = LuckyTickets.invl(P, 1 << 32)
        for i in range(h):
            for j in range(1 << i):
                s = j << (h - i)
                t = s | 1 << (h - i - 1)
                for k in range(1 << (h - i - 1)):
                    u = (dst[s + k] - dst[t + k] + 2 * P) * wws[k] % P
                    dst[s + k] = (dst[s + k] + dst[t + k]) % (2 * P)
                    Q = ((u << 32) * J) >> 32
                    dst[t + k] = (u >> 32) - (Q * P >> 32) + P
            if i < h - 1:
                for k in range(1 << (h - i - 2)):
                    wws[k] = wws[k * 2]
        for i in range(n):
            if dst[i] >= P:
                dst[i] -= P
        for i in range(n):
            rev = int('{:b}'.format(i).zfill(h)[::-1], 2)
            if i < rev:
                dst[i], dst[rev] = dst[rev], dst[i]
        if inverse:
            in_val = LuckyTickets.invl(n, P)
            for i in range(n):
                dst[i] = LuckyTickets.modh(dst[i] * in_val, M, H, P)
        return dst

    @staticmethod
    def modh(a, M, h, mod):
        r = a - (((M * (a & ((1 << 31) - 1))) >> 31) + (M * (a >> 31)) >> (h - 31)) * mod
        return r if r < mod else r - mod

    @staticmethod
    def pow(a, n, mod):
        ret = 1
        for x in range(n.bit_length() - 1, -1, -1):
            ret = ret * ret % mod
            if (n >> x) & 1:
                ret = ret * a % mod
        return ret

    @staticmethod
    def invl(a, mod):
        b = mod
        p, q = 1, 0
        while b > 0:
            c = a // b
            d = a
            a = b
            b = d % b
            d = p
            p = q
            q = d - c * q
        return p + mod if p < 0 else p

def main():
    input_data = sys.stdin.read().strip().split()
    N = int(input_data[0])
    k = int(input_data[1])
    vals = list(map(int, input_data[2:2 + k]))
    solver = LuckyTickets()
    result = solver.solve(N, k, vals)
    print(result)

if __name__ == "__main__":
    main()

